}

exercises.starter:
function makeAccumulator(start) {
  // return a function that adds its argument to a running total and returns it
}

exercises.solution:
function makeAccumulator(start) {
  let total = start
  return n => {
    total += n
    return total
  }
}

tests.setup:
const a = makeAccumulator(0)
const b = makeAccumulator(50)
