exercises.starter:
function makeTally() {
  // return a function that counts how many times each label has been seen
}

exercises.solution:
function makeTally() {
  const counts = {}
  return label => {
    counts[label] = (counts[label] || 0) + 1
    return counts[label]
  }
}

tests.setup:
const t1 = makeTally()
const t2 = makeTally()
t1('a')
t1('a')

exercises.starter:
function once(f) {
  // return a function that calls f only on its first invocation, then reuses the result
}

exercises.solution:
function once(f) {
  let called = false
  let result
  return (...args) => {
    if (!called) {
      called = true
      result = f(...args)
    }
    return result
  }
}

tests.setup:
let n = 0
const inc = once(() => ++n)
inc()

const a = once(() => 'a')
const b = once(() => 'b')
a()
